,args={}}}},result1={{type="doc",args={"YEL柳七刀：我以柳姓行走多年，早已无法分割……或许在我出走的那一刻，她的谢姓故人便已长逝。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL柳七刀：昨日询问小友的问题，我选择了前者，但我师妹选择了后者，我们争执不下。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL柳七刀：最终，我一意孤行，远走江湖，与她再不相见。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL柳七刀：我也说不清是否后悔，只是年已蹉跎，时常感怀旧事。NOR"}}},caozuoName2="给予",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"35028",5}},{type="itemout",args={"23dwjqwp21",1}},{type="tips",args={"失去老酒*1"}},{type="doc",args={"YEL柳七刀：都说世事无常，其实因果早已潜藏。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL柳七刀：我师父曾因一念之差，错杀好人，种了恶因，食了恶果。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL柳七刀：我仇恨难忘，不顾劝阻，执意远走，终是不虑前事之失，复循覆车之轨，又结恶果。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL柳七刀：生死我早有预料，我无怨无恨，徘徊几日只是故人难忘。但依她脾性，只怕是不会再见我。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL柳七刀：最后再拜托小友一件事，还请小友将这块玉佩交给宝三娘，交给她就好，其他不必多言。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL柳七刀：这几日多受小友照拂，“谢”字我就不多说了，我们日后……。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"CYN柳七刀仰天饮下一口酒，没有再说话，孤身一人往郊外离开，你知道你们或许不会再见了。NOR"}},{type="itemin",args={"23dwjqwp24",1}},{type="tips",args={"获得玉佩*1"}},{type="outobject",args={"rwnpc0605a"}},{type="refresh",args={}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rwnpc0602={id="rwnpc0602",baseId="rwnpc0602",combatid={1,1001},name="宝三娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"35028",4}},{type="doc",args={"YEL宝三娘：可否问问，少侠的老友可有告之他的名字？是姓柳还是姓谢？NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL宝三娘：我宝三娘活过半百，只认识一位姓柳的故人，那便是我师父，早已仙逝。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL宝三娘：既不是故人，那我便不需去见。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="doc",args={"YEL宝三娘：这有壶老酒，是为故人所留，但既然故人回不来也就不需要再留着了，少侠喝了也好，送人也罢，全凭少侠做主。NOR"}},{type="itemin",args={"23dwjqwp21",1}},{type="tips",args={"获得老酒*1"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL宝三娘：一别三十五春秋，原是早已隔人世。NOR"}},{type="outobject",args={"rwnpc0602"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="itemgreater",args={"23dwjqwp14",0}}}},autoResult1={{type="change",args={"rwnpc0602","rwnpc0602a"}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}},rwnpc0602a={id="rwnpc0602a",baseId="rwnpc0602",combatid={1,1001},name="宝三娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL宝三娘：我还以为少侠今日不会来了呢，可还有事？NOR"}}},caozuoName2="给予",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"35028",7}},{type="itemout",args={"23dwjqwp24",1}},{type="tips",args={"失去玉佩*1"}},{type="doc",args={"YEL宝三娘：物是人非事事休，情深到底是缘浅。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}},{type="outgame",args={"hdrole0607"}},{type="refresh",args={}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="redoc",args={"YEL宝三娘：我去见他又如何，不去见他又如何，往事无法改，来日已注定，再见也就徒增伤悲。NOR","YEL宝三娘：我所思念的人，都已长逝，但也无妨，终会在泉下相遇。NOR","YEL宝三娘：少侠来的第一日，我便知是受谁所托。一别数年未曾归过，此次回来应是诀别。他自己选的路，他无悔便好，我没什么好说的，也不需要再相见。NOR"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={}}}0000